import java.io.*;
import java.text.DecimalFormat;
import java.util.*;
import java.util.stream.IntStream;

public class c_v1 {

    public static void main(String[] args) {
        FS in = new FS(System.in);
        int n = in.nextInt();
        Circle[] circles = new Circle[n];
        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(new Vec(in.nextInt(), in.nextInt()), in.nextInt());
        }

        List<Vec> allPoints = new ArrayList<>();
        int[] parent = new int[n];
        IntStream.range(0, n).forEach(i -> parent[i] = i);
        int result = 1;

        for (int i = 0; i < n; i++) {
            List<Vec> currentIntersections = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                Vec[] intersections = circles[i].intersect(circles[j]);
                if (intersections == null) continue;

                int rootI = find(parent, i);
                int rootJ = find(parent, j);
                parent[rootI] = rootJ;

                outerLoop: for (Vec point : intersections) {
                    for (Vec existing : currentIntersections) {
                        if (point.equals(existing)) continue outerLoop;
                    }
                    currentIntersections.add(point);
                }
            }

            result += currentIntersections.size();

            outerLoop2: for (Vec point : currentIntersections) {
                for (Vec existing : allPoints) {
                    if (point.equals(existing)) continue outerLoop2;
                }
                allPoints.add(point);
            }
        }

        result -= allPoints.size();
        int connectedComponents = (int) IntStream.range(0, n)
                .filter(i -> parent[i] == i)
                .count();
        result += connectedComponents;

        System.out.println(result);
    }

    private static int find(int[] parent, int i) {
        if (parent[i] != i) {
            parent[i] = find(parent, parent[i]);
        }
        return parent[i];
    }

    static class Circle {
        Vec center;
        double radius;

        public Circle(Vec center, double radius) {
            this.center = center;
            this.radius = radius;
        }

        public boolean contains(Vec v) {
            return center.sub(v).mag2() - Vec.EPS * Vec.EPS <= radius * radius;
        }

        public Vec[] intersect(Circle other) {
            if (center.equals(other.center)) return null;
            Vec direction = other.center.sub(center);
            double distSq = direction.mag2();
            double distance = Math.sqrt(distSq);

            if (radius + other.radius < distance || radius + distance < other.radius || other.radius + distance < radius) {
                return null;
            }

            if (Vec.eq(radius + other.radius, distance) || Vec.eq(other.radius + distance, radius)) {
                return new Vec[]{center.add(direction.scale(radius / distance))};
            }
            if (Vec.eq(radius + distance, other.radius)) {
                return new Vec[]{center.sub(direction.scale(radius / distance))};
            }

            double d1 = (radius * radius + distSq - other.radius * other.radius) / (2 * distance);
            double h = Math.sqrt(radius * radius - d1 * d1);
            Vec unitDir = direction.unit();
            Vec rightInt = center.add(unitDir.scale(d1).add(unitDir.rot270().scale(h)));
            Vec leftInt = center.add(unitDir.scale(d1).add(unitDir.rot90().scale(h)));
            return new Vec[]{rightInt, leftInt};
        }
    }

    static class Vec {
        static final double EPS = 1e-9;
        double x, y;

        public Vec(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vec add(Vec other) { return new Vec(x + other.x, y + other.y); }
        public Vec sub(Vec other) { return new Vec(x - other.x, y - other.y); }
        public Vec scale(double s) { return new Vec(x * s, y * s); }
        public double dot(Vec other) { return x * other.x + y * other.y; }
        public double cross(Vec other) { return x * other.y - y * other.x; }
        public double mag2() { return dot(this); }
        public double mag() { return Math.sqrt(mag2()); }
        public Vec unit() { return scale(1 / mag()); }
        public Vec rot90() { return new Vec(-y, x); }
        public Vec rot270() { return new Vec(y, -x); }

        public Vec rotate(double theta) {
            double newX = x * Math.cos(theta) + y * Math.cos(Math.PI / 2 + theta);
            double newY = x * Math.sin(theta) + y * Math.sin(Math.PI / 2 + theta);
            return new Vec(newX, newY);
        }

        public double angle() {
            return (Math.atan2(y, x) + 2 * Math.PI) % (2 * Math.PI);
        }

        public String toString() {
            DecimalFormat df = new DecimalFormat("#.##");
            return "(" + df.format(x) + ", " + df.format(y) + ")";
        }

        static boolean eq(double a, double b) { return Math.abs(a - b) < EPS; }
        static boolean leq(double a, double b) { return a - EPS < b; }
        static boolean geq(double a, double b) { return a + EPS > b; }

        public boolean equals(Object obj) {
            Vec other = (Vec) obj;
            return eq(x, other.x) && eq(y, other.y);
        }
    }

    static class FS {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FS(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    return next();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
